select a.status, date_format(a.opened_date, 'yyyy-MM') as opened_month, count(case when t.txn_type = 'DEBIT' then 1 end) as debit_count from transactions t right join accounts a on t.account_id = a.id left join customers c on a.customer_id = c.id where month(a.opened_date) in (5, 8, 12) group by a.status, date_format(a.opened_date, 'yyyy-MM') having count(case when t.txn_type = 'DEBIT' then 1 end) >= 1;
